import { DomainError } from "./errors";

export interface Product {
  readonly id: string;
  readonly name: string;
  stock: number;
}

export function reserveStock(product: Product, quantity: number): void {
  if (product.stock < quantity) {
    throw new DomainError(
      "conflict",
      `Insufficient stock for product ${product.id}: requested ${quantity}, available ${product.stock}`,
    );
  }
  product.stock -= quantity;
}

export function releaseStock(product: Product, quantity: number): void {
  product.stock += quantity;
}

